48	    const text = `${saveAll([screw])}\n\n${serialize(nut)}\n`;
49	    deepStrictEqual(loadAll(text), [screw, nut]);
50	  });
51	
52	  it('пустой файл — пустой каталог', () => {
53	    deepStrictEqual(loadAll(''), []);
54	  });
55	});
56

