3	 *
4	 * Одна запись — одна строка JSON, файл — строки через `\n`. Формат — публичный контракт:
5	 * файлы каталога читают внешние службы (витрина, склад, выгрузка в бухгалтерию), и любое
6	 * изменение имён полей здесь — изменение для них. Поэтому набор и порядок полей в строке
7	 * закреплены явно, а не оставлены на усмотрение того, в каком порядке поля легли в объект:
8	 * diff двух выгрузок обязан показывать изменение данных, а не перестановку ключей.
9	 *
10	 * parse проверяет форму, а не доверяет JSON.parse: файл на диске мог написать кто угодно,
11	 * и «undefined в цене» всплыл бы не здесь, а в сумме заказа.
12	 */
13	
14	import { product } from './product.ts';
15	import type { Product } from './product.ts';
16	
17	/**
18	 * Одна запись → одна строка JSON без переносов. Порядок полей — как в таблице README.
19	 *
20	 * Пишется только новое имя `sku`; дубль старого `code` не ставится: строка с обоими именами
21	 * внешними службами прочитается по-разному — каждая возьмёт свой ключ.
22	 */
23	export function serialize(p: Product): string {
24	  return JSON.stringify({ sku: p.sku, title: p.title, priceK: p.priceK });
25	}
26	
27	/**
28	 * Одна строка файла → запись. Всё, что не запись каталога, отвергается с названной причиной.
29	 *
30	 * Чится и новое имя `sku`, и старое `code`: старые записи писали под именем `code`, и файл на
31	 * диске мог сохранить кто-до переименования (или отредактирован вручную). Если в строке оба
32	 * имени — побеждает `sku`: новое имя пишет наш код, старое могло остаться при ручной правке.
33	 */
34	export function parse(line: string): Product {
35	  let raw: unknown;
36	  try {
37	    raw = JSON.parse(line);
38	  } catch (e) {
39	    throw new SyntaxError(`строка каталога не разбирается как JSON: ${e instanceof Error ? e.message : String(e)}`);
40	  }
41	  if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) {
42	    throw new TypeError('строка каталога — не объект');
43	  }
44	  const r = raw as Record<string, unknown>;
45	  const fromSku = r['sku'];
46	  const fromCode = r['code'];
47	  const sku = typeof fromSku === 'string' ? fromSku : fromCode;
48	  const title = r['title'];
49	  const priceK = r['priceK'];
50	  if (typeof sku !== 'string') throw new TypeError('в строке каталога нет артикула (sku, старое имя — code)');
51	  if (typeof title !== 'string') throw new TypeError('в строке каталога нет названия (title)');
52	  if (typeof priceK !== 'number') throw new TypeError('в строке каталога нет цены (priceK)');
53	  // Диапазоны — те же, что у конструктора: правило одно и на ввод, и на чтение с диска.
54	  return product(sku, title, priceK);
55	}
56	
57	/** Каталог → текст файла JSONL. Каждая строка завершена `\n`, чтобы файлы склеивались конкатенацией. */
58	export function saveAll(products: readonly Product[]): string {
59	  let text = '';
60	  for (const p of products) text += `${serialize(p)}\n`;
61	  return text;
62	}
63	
64	/** Текст файла JSONL → каталог. Пустые строки (в т.ч. хвостовой перевод строки) записями не считаются. */
65	export function loadAll(text: string): Product[] {
66	  const out: Product[] = [];
67	  for (const line of text.split('\n')) {
68	    if (line.trim() === '') continue;
69	    out.push(parse(line));
70	  }
71	  return out;
72	}
