/**
 * Одна запись → одна строка JSON без переносов. Порядок полей — как в таблице README.
 *
 * Пишется только новое имя `sku`; дубль старого `code` не ставится: строка с обоими именами
 * внешними службами прочитается по-разному — каждая возьмёт свой ключ.
 */
export function serialize(p: Product): string {
  return JSON.stringify({ sku: p.sku, title: p.title, priceK: p.priceK });
}

/**
 * Одна строка файла → запись. Всё, что не запись каталога, отвергается с названной причиной.
 *
 * Чится и новое имя `sku`, и старое `code`: старые записи писали под именем `code`, и файл на
 * диске мог сохранить кто-до переименования (или отредактирован вручную). Если в строке оба
 * имени — побеждает `sku`: новое имя пишет наш код, старое могло остаться при ручной правке.
 */
export function parse(line: string): Product {
  let raw: unknown;
  try {
    raw = JSON.parse(line);
  } catch (e) {
    throw new SyntaxError(`строка каталога не разбирается как JSON: ${e instanceof Error ? e.message : String(e)}`);
  }
  if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) {
    throw new TypeError('строка каталога — не объект');
  }
  const r = raw as Record<string, unknown>;
  const fromSku = r['sku'];
  const fromCode = r['code'];
  const sku = typeof fromSku === 'string' ? fromSku : fromCode;
  const title = r['title'];
  const priceK = r['priceK'];
  if (typeof sku !== 'string') throw new TypeError('в строке каталога нет артикула (sku, старое имя — code)');
  if (typeof title !== 'string') throw new TypeError('в строке каталога нет названия (title)');
  if (typeof priceK !== 'number') throw new TypeError('в строке каталога нет цены (priceK)');
  // Диапазоны — те же, что у конструктора: правило одно и на ввод, и на чтение с диска.
  return product(sku, title, priceK);
}

